 "content": "from collections import Counter, deque


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    frames = []
    frame_cells = set()

    # Each outlined rectangle is a large monochrome 4-connected component;
    # isolated cells are the scattered color-count markers.
    for r in range(h):
        for c in range(w):
            if not g[r][c] or (r, c) in seen:
                continue
            color = g[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and g[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            if len(comp) < 8:
                continue
            r0 = min(y for y, x in comp); r1 = max(y for y, x in comp)
            c0 = min(x for y, x in comp); c1 = max(x for y, x in comp)
            border = {(y, x) for y in range(r0, r1 + 1) for x in range(c0, c1 + 1)
                      if y in (r0, r1) or x in (c0, c1)}
            if set(comp) == border and r1 - r0 >= 2 and c1 - c0 >= 2:
                frames.append((color, r0, r1, c0, c1))
                frame_cells.update(border)

    markers = Counter(g[r][c] for r in range(h) for c in range(w)
                      if g[r][c] and (r, c) not in frame_cells)
    # Remove the scattered count markers.
    for r in range(h):
        for c in range(w):
            if (r, c) not in frame_cells:
                g[r][c] = 0

    for _, r0, r1, c0, c1 in frames:
        cells = [(r, c) for r in range(r0 + 1, r1)
                 for c in range(c0 + 1, c1)
                 if (r + c) % 2 == (r0 + 1 + c0 + 1) % 2]
        n = len(cells)
        color = next((k for k, count in markers.items() if count == n), None)
        if color is not None:
            for r, c in cells:
                g[r][c] = color
    return g
